import{_ as e,o as r,c as n,a0 as l}from"./chunks/framework.n1c-_RXi.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core/engine/engine.md","filePath":"core/engine/engine.md"}'),a={name:"core/engine/engine.md"};function o(s,t,d,i,g,c){return r(),n("div",null,[...t[0]||(t[0]=[l('<h6 id="version-0-7-1" tabindex="-1">version: 0.7.1 <a class="header-anchor" href="#version-0-7-1" aria-label="Permalink to &quot;version: 0.7.1&quot;">​</a></h6><hr><h2 id="engine" tabindex="-1">Engine <a class="header-anchor" href="#engine" aria-label="Permalink to &quot;Engine&quot;">​</a></h2><h2 id="engine-1" tabindex="-1">Engine <a class="header-anchor" href="#engine-1" aria-label="Permalink to &quot;Engine&quot;">​</a></h2><p>Control engine properties and define defaults used across the whole project. <code>Engine</code> is entirely static — never instantiated. It manages the scene stack, canvas size and scaling, the update loop, platform queries, and all frame/input callback events.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Property</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./../../incomplete-docs.html"><strong>Scaling</strong></a></td><td style="text-align:left;"><a href="./engine-scaling-mode.html"><strong>scalingMode</strong></a></td><td style="text-align:left;">How the logical canvas maps to the physical window.</td></tr><tr><td style="text-align:left;"><a href="./../../incomplete-docs.html"><strong>TextureStrategy</strong></a></td><td style="text-align:left;"><a href="./engine-texture-strategy.html"><strong>textureStrategy</strong></a></td><td style="text-align:left;">Automatic resizing of non-power-of-two textures.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-call-mouse-in-touch-event.html"><strong>callMouseInTouchEvent</strong></a></td><td style="text-align:left;">Whether touch input also fires mouse events.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-call-touch-in-mouse-event.html"><strong>callTouchInMouseEvent</strong></a></td><td style="text-align:left;">Whether mouse input also fires touch events.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-use-degrees.html"><strong>useDegrees</strong></a></td><td style="text-align:left;">Whether angle parameters use degrees (<code>true</code>) or radians.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-allow-events-out-canvas.html"><strong>allowEventsOutCanvas</strong></a></td><td style="text-align:left;">Whether mouse move/scroll events fire outside the canvas.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-ignore-events-handled-by-ui.html"><strong>ignoreEventsHandledByUI</strong></a></td><td style="text-align:left;">Whether gameplay input skips events consumed by UI.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a></td><td style="text-align:left;"><a href="./engine-update-time.html"><strong>updateTime</strong></a></td><td style="text-align:left;">Fixed-update interval in seconds driving <code>onFixedUpdate</code> and physics.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/double" target="_blank" rel="noreferrer"><strong>double</strong></a></td><td style="text-align:left;"><a href="./engine-interpolation-alpha.html"><strong>interpolationAlpha</strong></a></td><td style="text-align:left;">Blend factor between fixed-update steps for the current frame.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a></td><td style="text-align:left;"><a href="./engine-canvas-size.html"><strong>canvasWidth</strong></a> / <a href="./engine-canvas-size.html"><strong>canvasHeight</strong></a></td><td style="text-align:left;">Logical canvas size after scaling.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a></td><td style="text-align:left;"><a href="./engine-preferred-canvas-size.html"><strong>preferredCanvasWidth</strong></a> / <a href="./engine-preferred-canvas-size.html"><strong>preferredCanvasHeight</strong></a></td><td style="text-align:left;">Canvas size passed to <code>setCanvasSize</code>.</td></tr><tr><td style="text-align:left;"><a href="./../maths/rect/rect.html"><strong>Rect</strong></a></td><td style="text-align:left;"><a href="./engine-view-rect.html"><strong>viewRect</strong></a></td><td style="text-align:left;">Viewport rectangle from canvas size, screen size, and scaling mode.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a></td><td style="text-align:left;"><a href="./engine-deltatime.html"><strong>deltatime</strong></a></td><td style="text-align:left;">Seconds since the last draw frame, clamped by <code>maxDeltatime</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a></td><td style="text-align:left;"><a href="./engine-max-deltatime.html"><strong>maxDeltatime</strong></a></td><td style="text-align:left;">Upper bound for <code>deltatime</code> (default <code>0.25</code>).</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a></td><td style="text-align:left;"><a href="./engine-framerate.html"><strong>framerate</strong></a></td><td style="text-align:left;">Current frames-per-second estimate.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/double" target="_blank" rel="noreferrer"><strong>double</strong></a></td><td style="text-align:left;"><a href="./engine-system-time.html"><strong>systemTime</strong></a></td><td style="text-align:left;">Monotonic wall-clock time in seconds.</td></tr><tr><td style="text-align:left;"><a href="./../../incomplete-docs.html"><strong>Platform</strong></a></td><td style="text-align:left;"><a href="./engine-platform.html"><strong>platform</strong></a></td><td style="text-align:left;">Platform the engine is running on.</td></tr><tr><td style="text-align:left;"><a href="./../../incomplete-docs.html"><strong>GraphicBackend</strong></a></td><td style="text-align:left;"><a href="./engine-graphic-backend.html"><strong>graphicBackend</strong></a></td><td style="text-align:left;">Active graphics backend.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-open-gl.html"><strong>openGL</strong></a></td><td style="text-align:left;">Whether an OpenGL backend is active.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-async-loading.html"><strong>asyncLoading</strong></a></td><td style="text-align:left;">Whether background resource loading is enabled.</td></tr><tr><td style="text-align:left;"><a href="./../../incomplete-docs.html"><strong>CursorType</strong></a></td><td style="text-align:left;"><a href="./engine-mouse-cursor.html"><strong>mouseCursor</strong></a></td><td style="text-align:left;">OS mouse cursor shape.</td></tr><tr><td style="text-align:left;"><a href="./../../incomplete-docs.html"><strong>MouseMode</strong></a></td><td style="text-align:left;"><a href="./engine-mouse-mode.html"><strong>mouseMode</strong></a></td><td style="text-align:left;">Mouse visibility and capture behaviour.</td></tr><tr><td style="text-align:left;"><strong><a href="./../../incomplete-docs.html"><strong>Framebuffer*</strong></a></strong></td><td style="text-align:left;"><a href="./engine-framebuffer.html"><strong>framebuffer</strong></a></td><td style="text-align:left;">Off-screen render target for full-frame output.</td></tr></tbody></table><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><p><code>Engine</code> is entirely static and cannot be instantiated, so it exposes no public constructors. Configure it through its static properties and methods, typically from the <code>init()</code> function registered with <code>DORIAX_INIT</code>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Result</th><th style="text-align:left;">Method</th><th style="text-align:left;">Arguments</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-set-scene.html"><strong>setScene</strong></a></td><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>* scene</td><td style="text-align:left;">Sets the main scene.</td></tr><tr><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>*</td><td style="text-align:left;"><a href="./engine-get-scene.html"><strong>getScene</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Returns the current main scene.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-add-scene-layer.html"><strong>addSceneLayer</strong></a></td><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>* scene</td><td style="text-align:left;">Renders an additional scene as a layer on top of the main scene.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-execute-scene-once.html"><strong>executeSceneOnce</strong></a></td><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>* scene</td><td style="text-align:left;">Runs a scene for a single draw, then removes it automatically.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-remove-scene.html"><strong>removeScene</strong></a></td><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>* scene</td><td style="text-align:left;">Removes a specific scene from the active scene stack.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-remove-all-scene-layers.html"><strong>removeAllSceneLayers</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a> removeOneTimeScenes</td><td style="text-align:left;">Removes all layered scenes.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-remove-all-scenes.html"><strong>removeAllScenes</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Removes all scenes, including the main scene and all layers.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-is-scene-running.html"><strong>isSceneRunning</strong></a></td><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>* scene</td><td style="text-align:left;">Whether the given scene is in the active scene stack.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-has-scenes-to-execute-once.html"><strong>hasScenesToExecuteOnce</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Whether any one-shot scene is still waiting to be drawn.</td></tr><tr><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>*</td><td style="text-align:left;"><a href="./engine-get-main-scene.html"><strong>getMainScene</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Returns the scene set with <code>setScene</code>.</td></tr><tr><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>*</td><td style="text-align:left;"><a href="./engine-get-last-scene.html"><strong>getLastScene</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Returns the top-most scene in the stack.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-pause-game-events.html"><strong>pauseGameEvents</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a> pause</td><td style="text-align:left;">Pauses gameplay event delivery without stopping rendering.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-set-canvas-size.html"><strong>setCanvasSize</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a> canvasWidth, <a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a> canvasHeight</td><td style="text-align:left;">Sets the preferred logical canvas dimensions.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-set-mouse-position.html"><strong>setMousePosition</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a> x, <a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a> y</td><td style="text-align:left;">Sets the mouse position in logical canvas coordinates.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-set-update-time-ms.html"><strong>setUpdateTimeMS</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/unsigned" target="_blank" rel="noreferrer"><strong>unsigned</strong></a> <a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a> updateTimeMS</td><td style="text-align:left;">Sets the fixed-update interval in milliseconds.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-is-ui-event-received.html"><strong>isUIEventReceived</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Whether any UI widget consumed a pointer event this frame.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-is-view-loaded.html"><strong>isViewLoaded</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Whether the graphics surface is ready.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-set-max-resource-loading-threads.html"><strong>setMaxResourceLoadingThreads</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/w/cpp/types/size_t" target="_blank" rel="noreferrer"><strong>size_t</strong></a> maxThreads</td><td style="text-align:left;">Sets the worker thread count for background asset loading.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/w/cpp/types/size_t" target="_blank" rel="noreferrer"><strong>size_t</strong></a></td><td style="text-align:left;"><a href="./engine-get-queued-resource-count.html"><strong>getQueuedResourceCount</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Resources still waiting on background loading threads.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-clear-pools.html"><strong>clearPools</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Fully clears all resource caches. C++ only.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-clear-unused-pools.html"><strong>clearUnusedPools</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Clears only unreferenced resource cache entries. C++ only.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-clear-all-subscriptions.html"><strong>clearAllSubscriptions</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a> includeLifecycle</td><td style="text-align:left;">Removes all registered engine event callbacks.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-clear-component-subscriptions.html"><strong>clearComponentSubscriptions</strong></a></td><td style="text-align:left;"><a href="./../scene/scene.html"><strong>Scene</strong></a>* scene</td><td style="text-align:left;">Removes callbacks registered on a scene&#39;s components.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-remove-subscriptions-by-tag.html"><strong>removeSubscriptionsByTag</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/const" target="_blank" rel="noreferrer"><strong>const</strong></a> <a href="https://en.cppreference.com/w/cpp/string/basic_string" target="_blank" rel="noreferrer"><strong>std::string</strong></a>&amp; substring</td><td style="text-align:left;">Removes subscriptions whose tag contains the substring.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-async-thread.html"><strong>startAsyncThread</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Marks the current worker thread for GPU resource creation.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-async-thread.html"><strong>commitThreadQueue</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Flushes pending GPU uploads on the main thread.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a></td><td style="text-align:left;"><a href="./engine-async-thread.html"><strong>endAsyncThread</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Unmarks the current worker thread.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./engine-async-thread.html"><strong>isAsyncThread</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Whether the calling thread is a marked worker thread.</td></tr><tr><td style="text-align:left;"><strong><a href="./../../incomplete-docs.html"><strong>FunctionSubscribe</strong></a>&lt;<a href="https://en.cppreference.com/cpp/keyword/void" target="_blank" rel="noreferrer"><strong>void</strong></a>()&gt;&amp;</strong></td><td style="text-align:left;"><a href="./engine-get-on-init.html"><strong>getOnInit</strong></a></td><td style="text-align:left;"></td><td style="text-align:left;">Safe accessor for the Init event.</td></tr></tbody></table><h2 id="callback-events" tabindex="-1">Callback events <a class="header-anchor" href="#callback-events" aria-label="Permalink to &quot;Callback events&quot;">​</a></h2><p>Subscribe with <code>Engine::eventName.add(&quot;tag&quot;, &amp;callback)</code> from C++, or with the <code>REGISTER_ENGINE_EVENT(method)</code> macro inside a <code>testerScript</code>. Startup code belongs in the <code>init()</code> function registered with <code>DORIAX_INIT</code> (see <code>getOnInit</code>).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Callback</th><th style="text-align:left;">Event</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onViewLoaded</code></td><td style="text-align:left;">Fired once when the graphics surface is ready for rendering.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onViewChanged</code></td><td style="text-align:left;">Fired when the canvas or window size changes.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onViewDestroyed</code></td><td style="text-align:left;">Fired when the graphics surface is being destroyed.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onDraw</code></td><td style="text-align:left;">Fired every frame after the scene is drawn.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onUpdate</code></td><td style="text-align:left;">Fired every frame for variable-step gameplay logic.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onFixedUpdate</code></td><td style="text-align:left;">Fired at the fixed <code>updateTime</code> interval for physics and deterministic simulation.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onPostUpdate</code></td><td style="text-align:left;">Fired after the update and fixed-update passes each frame.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onPause</code></td><td style="text-align:left;">Fired when the system suspends the application.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onResume</code></td><td style="text-align:left;">Fired when the application returns to the foreground.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onShutdown</code></td><td style="text-align:left;">Fired when the application is closing.</td></tr><tr><td style="text-align:left;"><code>void(int,float,float)</code></td><td style="text-align:left;"><code>onTouchStart</code></td><td style="text-align:left;">A new touch contact begins.</td></tr><tr><td style="text-align:left;"><code>void(int,float,float)</code></td><td style="text-align:left;"><code>onTouchEnd</code></td><td style="text-align:left;">A touch contact is lifted.</td></tr><tr><td style="text-align:left;"><code>void(int,float,float)</code></td><td style="text-align:left;"><code>onTouchMove</code></td><td style="text-align:left;">A touch contact moves.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onTouchCancel</code></td><td style="text-align:left;">The system cancels the current touch sequence.</td></tr><tr><td style="text-align:left;"><code>void(int,float,float,int)</code></td><td style="text-align:left;"><code>onMouseDown</code></td><td style="text-align:left;">A mouse button is pressed.</td></tr><tr><td style="text-align:left;"><code>void(int,float,float,int)</code></td><td style="text-align:left;"><code>onMouseUp</code></td><td style="text-align:left;">A mouse button is released.</td></tr><tr><td style="text-align:left;"><code>void(float,float,int)</code></td><td style="text-align:left;"><code>onMouseMove</code></td><td style="text-align:left;">The mouse cursor moves.</td></tr><tr><td style="text-align:left;"><code>void(float,float,int)</code></td><td style="text-align:left;"><code>onMouseScroll</code></td><td style="text-align:left;">The mouse scroll wheel changes.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onMouseEnter</code></td><td style="text-align:left;">The mouse cursor enters the canvas boundary.</td></tr><tr><td style="text-align:left;"><code>void()</code></td><td style="text-align:left;"><code>onMouseLeave</code></td><td style="text-align:left;">The mouse cursor leaves the canvas boundary.</td></tr><tr><td style="text-align:left;"><code>void(int,bool,int)</code></td><td style="text-align:left;"><code>onKeyDown</code></td><td style="text-align:left;">A keyboard key is pressed.</td></tr><tr><td style="text-align:left;"><code>void(int,bool,int)</code></td><td style="text-align:left;"><code>onKeyUp</code></td><td style="text-align:left;">A keyboard key is released.</td></tr><tr><td style="text-align:left;"><code>void(wchar_t)</code></td><td style="text-align:left;"><code>onCharInput</code></td><td style="text-align:left;">Text input, including composed characters.</td></tr><tr><td style="text-align:left;"><code>void(int)</code></td><td style="text-align:left;"><code>onGamepadConnect</code></td><td style="text-align:left;">A controller is connected.</td></tr><tr><td style="text-align:left;"><code>void(int)</code></td><td style="text-align:left;"><code>onGamepadDisconnect</code></td><td style="text-align:left;">A controller is disconnected.</td></tr><tr><td style="text-align:left;"><code>void(int,int)</code></td><td style="text-align:left;"><code>onGamepadButtonDown</code></td><td style="text-align:left;">A controller button is pressed.</td></tr><tr><td style="text-align:left;"><code>void(int,int)</code></td><td style="text-align:left;"><code>onGamepadButtonUp</code></td><td style="text-align:left;">A controller button is released.</td></tr><tr><td style="text-align:left;"><code>void(int,int,float)</code></td><td style="text-align:left;"><code>onGamepadAxisMove</code></td><td style="text-align:left;">A controller analog axis changes.</td></tr></tbody></table><hr><p>Found an issue? <a href="https://github.com/JordanGrant3D/doriax-jord-docs/issues" target="_blank" rel="noreferrer">Report it here</a>.</p>',16)])])}const p=e(a,[["render",o]]);export{h as __pageData,p as default};
